// Navigation Handling
function initNavigation() {
  const tabs = document.querySelectorAll(".nav-tab");
  const views = document.querySelectorAll(".tab-view");

  tabs.forEach(tab => {
    tab.addEventListener("click", () => {
      const targetView = tab.getAttribute("data-target");

      tabs.forEach(t => {
        t.classList.remove("active", "bg-orange-500", "text-white", "shadow-orange-500/25");
        t.classList.add("text-slate-300", "hover:bg-slate-800");
      });

      tab.classList.add("active", "bg-orange-500", "text-white", "shadow-orange-500/25");
      tab.classList.remove("text-slate-300", "hover:bg-slate-800");

      views.forEach(v => {
        if (v.id === targetView) {
          v.classList.remove("hidden");
        } else {
          v.classList.add("hidden");
        }
      });

      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  });
}

// Arrhenius Thermodynamic Helpers
function calculateRateConstant(A, Ea_kJ_mol, tempCelsius) {
  const T_kelvin = tempCelsius + 273.15;
  if (T_kelvin <= 0) return 0;
  const Ea_joules = Ea_kJ_mol * 1000.0;
  return A * Math.exp(-Ea_joules / (R_GAS * T_kelvin));
}

function firstOrderDecay(c0, k, earthDays) {
  return c0 * Math.exp(-k * earthDays);
}

// View 1: Dashboard Logic
function initDashboard() {
  const solSlider = document.getElementById("dashboardSolSlider");
  const solDisplay = document.getElementById("currentSolDisplay");
  const earthDaysDisplay = document.getElementById("earthDaysDisplay");
  const securityGauge = document.getElementById("securityGaugeVal");
  const securityBar = document.getElementById("securityProgressBar");
  const daysRations = document.getElementById("daysRationsVal");
  const remainingMass = document.getElementById("remainingMassVal");
  const cropYield = document.getElementById("cropYieldVal");
  const coolingPower = document.getElementById("coolingPowerVal");

  function updateDashboard(sol) {
    const crewSize = 4;
    solDisplay.textContent = `SOL ${sol}`;
    earthDaysDisplay.textContent = `${(sol * SOL_IN_EARTH_DAYS).toFixed(0)} Earth Days`;

    const initialMassKg = crewSize * 1.6 * 600 * 1.2;
    const consumedMassKg = crewSize * 1.5 * sol;
    const remainingKg = Math.max(0, initialMassKg - consumedMassKg);
    const daysLeft = (remainingKg / (crewSize * 1.5)).toFixed(1);
    const securityPct = Math.min(100, Math.max(0, Math.round((daysLeft / 150) * 100)));

    securityGauge.textContent = `${securityPct}%`;
    securityBar.style.width = `${securityPct}%`;
    daysRations.textContent = daysLeft;
    remainingMass.textContent = `${remainingKg.toFixed(1)} kg`;
    cropYield.textContent = `5,445 g/Sol`;

    const powerKw = ((remainingKg * 0.45 + 18.0 * 120.0) / 1000.0).toFixed(2);
    coolingPower.textContent = `${powerKw} kW`;
  }

  if (solSlider) {
    solSlider.addEventListener("input", (e) => updateDashboard(parseInt(e.target.value)));
    updateDashboard(450);
  }

  document.querySelectorAll(".sol-quick-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const s = parseInt(btn.getAttribute("data-sol"));
      if (solSlider) {
        solSlider.value = s;
        updateDashboard(s);
      }
    });
  });
}

// View 2: Data Laboratory
function initDataLab() {
  const tbody = document.getElementById("foodCatalogTableBody");
  const filterBtns = document.querySelectorAll(".cat-filter-btn");
  const searchInput = document.getElementById("catalogSearchInput");
  let currentCategory = "ALL";
  let searchQuery = "";

  function renderTable() {
    if (!tbody) return;
    tbody.innerHTML = "";
    const filtered = SPACE_FOOD_CATALOG.filter(item => {
      const matchesCat = currentCategory === "ALL" || item.category === currentCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery) || item.id.toLowerCase().includes(searchQuery);
      return matchesCat && matchesSearch;
    });

    filtered.forEach(f => {
      const tr = document.createElement("tr");
      tr.className = "hover:bg-slate-800/40 transition border-b border-slate-800 text-xs font-mono";
      tr.innerHTML = `
        <td class="p-3">
          <span class="font-bold text-white block">${f.name}</span>
          <span class="text-[10px] text-orange-400">${f.id}</span>
        </td>
        <td class="p-3">
          <span class="px-2 py-0.5 rounded text-[10px] ${f.category === 'Bio-regenerative' ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/40' : 'bg-slate-800 border border-slate-700 text-slate-300'}">${f.category}</span>
          <span class="block text-[10px] text-slate-500 mt-0.5">${f.preservation}</span>
        </td>
        <td class="p-3 text-right text-slate-300">${f.serving_g}g</td>
        <td class="p-3 text-right font-bold text-white">${f.calories} kcal</td>
        <td class="p-3 text-right text-slate-300">${f.protein}g</td>
        <td class="p-3 text-right text-amber-400">${f.thiamine} mg</td>
        <td class="p-3 text-right text-emerald-400 font-bold">${f.vit_c} mg</td>
        <td class="p-3 text-right text-cyan-400">${f.Ea}</td>
        <td class="p-3 text-right font-bold text-orange-400">${f.shelf_life_4C} Sols</td>
      `;
      tbody.appendChild(tr);
    });
  }

  filterBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      filterBtns.forEach(b => {
        b.classList.remove("bg-orange-500", "text-white", "font-bold");
        b.classList.add("bg-slate-900", "text-slate-400");
      });
      btn.classList.add("bg-orange-500", "text-white", "font-bold");
      btn.classList.remove("bg-slate-900", "text-slate-400");
      currentCategory = btn.getAttribute("data-cat");
      renderTable();
    });
  });

  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      searchQuery = e.target.value.toLowerCase();
      renderTable();
    });
  }

  function renderBenchmarkTable() {
    const bTbody = document.getElementById("benchmarkTableBody");
    if (!bTbody) return;
    bTbody.innerHTML = "";
    JSC_BENCHMARKS.forEach(bm => {
      const tr = document.createElement("tr");
      tr.className = "text-slate-300 border-b border-slate-800/40 text-[11px] font-mono";
      tr.innerHTML = `
        <td class="py-2 text-white">${bm.name} <span class="text-orange-400">(${bm.nutrient})</span><br/><span class="text-slate-500">${bm.basis}</span></td>
        <td class="py-2">${bm.temp_c}°C</td>
        <td class="py-2 font-bold text-cyan-400">${bm.days} d</td>
        <td class="py-2 text-right">${bm.actual.toFixed(1)}%</td>
        <td class="py-2 text-right text-emerald-400 font-bold">${bm.predicted.toFixed(1)}%</td>
        <td class="py-2 text-right ${bm.res < 0 ? 'text-amber-400' : 'text-slate-400'}">${bm.res > 0 ? '+' : ''}${bm.res.toFixed(1)} pp</td>
        <td class="py-2 text-right font-bold ${bm.agrees ? 'text-emerald-400' : 'text-amber-400'}">${bm.agrees ? 'YES' : 'NO'}</td>
      `;
      bTbody.appendChild(tr);
    });
  }

  renderTable();
  renderBenchmarkTable();
}

// View 3: Synthetic greenhouse crop lab
function initGanjaBioLab() {
  const cultivarSelect = document.getElementById("ganjaCultivarSelect");
  const areaSlider = document.getElementById("ganjaAreaSlider");
  const areaVal = document.getElementById("ganjaAreaVal");
  const ppfdSlider = document.getElementById("ganjaPpfdSlider");
  const ppfdVal = document.getElementById("ganjaPpfdVal");
  const photoperiodSlider = document.getElementById("ganjaPhotoperiodSlider");
  const photoperiodVal = document.getElementById("ganjaPhotoperiodVal");

  const badgeTitle = document.getElementById("badgeCultivarTitle");
  const badgeDesc = document.getElementById("badgeCultivarDesc");

  const outDailyBiomass = document.getElementById("outDailyBiomass");
  const outDailyO2 = document.getElementById("outDailyO2");
  const outDailyCO2 = document.getElementById("outDailyCO2");
  const outDailyWater = document.getElementById("outDailyWater");
  const outDailyVitC = document.getElementById("outDailyVitC");
  const outPayloadSaved = document.getElementById("outPayloadSaved");

  function updateGanjaYields() {
    const cid = cultivarSelect.value;
    const c = GANJA_CULTIVARS_MAP[cid];
    const area = parseFloat(areaSlider.value);
    const ppfd = parseFloat(ppfdSlider.value);
    const photoperiod = parseFloat(photoperiodSlider.value);

    areaVal.textContent = `${area.toFixed(1)} m²`;
    ppfdVal.textContent = `${ppfd.toFixed(0)} µmol/m²/s`;
    photoperiodVal.textContent = `${photoperiod.toFixed(0)} h / Sol`;

    badgeTitle.textContent = c.name;
    badgeDesc.textContent = c.desc;

    // Light-use efficiency factor (relative to 400 umol at 16h)
    const nominalDli = (400.0 * 16.0 * 3600) / 1e6;
    const actualDli = (ppfd * photoperiod * 3600) / 1e6;
    const lueFactor = Math.min(1.35, Math.max(0.4, Math.sqrt(actualDli / nominalDli)));

    const dailyBiomassKg = (c.daily_g_m2 * area * lueFactor) / 1000.0;
    const dailyO2g = c.o2_g_m2 * area * lueFactor;
    const dailyCO2g = c.co2_g_m2 * area * lueFactor;
    const dailyWaterL = c.water_l_m2 * area;
    const dailyVitCmg = (dailyBiomassKg * 10.0) * c.vit_c_100g; // per 100g conversion
    const payloadSavedKg = dailyBiomassKg * 450 * 1.25;

    outDailyBiomass.textContent = `${dailyBiomassKg.toFixed(2)} kg/Sol`;
    outDailyO2.textContent = `${dailyO2g.toFixed(0)} g/Sol`;
    outDailyCO2.textContent = `${dailyCO2g.toFixed(0)} g/Sol`;
    outDailyWater.textContent = `${dailyWaterL.toFixed(1)} L/Sol`;
    outDailyVitC.textContent = `${dailyVitCmg.toFixed(0)} mg/Sol`;
    outPayloadSaved.textContent = `${payloadSavedKg.toFixed(0)} kg`;

    renderRegolithChart();
  }

  if (cultivarSelect) cultivarSelect.addEventListener("change", updateGanjaYields);
  if (areaSlider) areaSlider.addEventListener("input", updateGanjaYields);
  if (ppfdSlider) ppfdSlider.addEventListener("input", updateGanjaYields);
  if (photoperiodSlider) photoperiodSlider.addEventListener("input", updateGanjaYields);

  function renderRegolithChart() {
    const svg = document.getElementById("regolithSvgChart");
    if (!svg) return;
    const w = 680, h = 180, pad = 40;

    // Curve 1: Raw simulant (drops quickly with salinity)
    let rawPath = "";
    // Curve 2: Amended substrate (illustrative synthetic curve)
    let amendedPath = "";

    for (let ec = 0; ec <= 16; ec += 0.5) {
      const rawGerm = Math.max(0, 100.0 - ec * 8.5);
      const amendedGerm = Math.max(15, 100.0 - Math.pow(ec / 16.0, 1.8) * 45.0);

      const x = pad + (ec / 16.0) * (w - pad * 2);
      const yRaw = h - pad - (rawGerm / 100.0) * (h - pad * 2);
      const yAmended = h - pad - (amendedGerm / 100.0) * (h - pad * 2);

      rawPath += ec === 0 ? `M ${x} ${yRaw}` : ` L ${x} ${yRaw}`;
      amendedPath += ec === 0 ? `M ${x} ${yAmended}` : ` L ${x} ${yAmended}`;
    }

    svg.innerHTML = `
      <line x1="${pad}" y1="${h - pad}" x2="${w - pad}" y2="${h - pad}" stroke="#1e293b"/>
      <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${h - pad}" stroke="#1e293b"/>
      <!-- Grid lines -->
      <line x1="${pad}" y1="${h - pad - 0.5 * (h - pad * 2)}" x2="${w - pad}" y2="${h - pad - 0.5 * (h - pad * 2)}" stroke="#1e293b" stroke-dasharray="2 2"/>
      
      <!-- Axis Labels -->
      <text x="${w - pad}" y="${h - 10}" fill="#64748b" font-size="10" font-family="monospace" text-anchor="end">Salinity (dS/m)</text>
      <text x="${pad + 5}" y="${pad - 10}" fill="#64748b" font-size="10" font-family="monospace">Germination Rate (%)</text>
      
      <!-- Paths -->
      <path d="${rawPath}" fill="none" stroke="#ef4444" stroke-width="2" stroke-dasharray="4 4"/>
      <path d="${amendedPath}" fill="none" stroke="#10b981" stroke-width="3"/>
      
      <!-- Legend -->
      <text x="${w - pad - 10}" y="${pad + 15}" fill="#10b981" font-size="10" font-family="monospace" font-weight="bold" text-anchor="end">Amended Substrate (Synthetic Curve)</text>
      <text x="${w - pad - 10}" y="${pad + 30}" fill="#ef4444" font-size="10" font-family="monospace" text-anchor="end">Unamended Simulant (Synthetic Curve)</text>
    `;
  }

  updateGanjaYields();
}

// View 4: Arrhenius Prediction Engine
function initPredictionEngine() {
  const foodSelect = document.getElementById("predFoodSelect");
  const tempSlider = document.getElementById("predTempSlider");
  const tempDisplay = document.getElementById("predTempDisplay");
  const durationSlider = document.getElementById("predDurationSlider");
  const durationDisplay = document.getElementById("predDurationDisplay");

  const eaVal = document.getElementById("predEaVal");
  const kVal = document.getElementById("predKVal");
  const halfLifeVal = document.getElementById("predHalfLifeVal");
  const dropDeadVal = document.getElementById("predDropDeadVal");

  const sol450Thiamine = document.getElementById("predSol450Thiamine");
  const sol450VitC = document.getElementById("predSol450VitC");
  const sol450Sensory = document.getElementById("predSol450Sensory");

  if (foodSelect) {
    SPACE_FOOD_CATALOG.forEach(f => {
      const opt = document.createElement("option");
      opt.value = f.id;
      opt.textContent = `${f.id}: ${f.name} (${f.category})`;
      foodSelect.appendChild(opt);
    });
    foodSelect.value = "TH-001";
  }

  function updatePrediction() {
    const fId = foodSelect.value;
    const food = SPACE_FOOD_CATALOG.find(x => x.id === fId) || SPACE_FOOD_CATALOG[0];
    const tempC = parseFloat(tempSlider.value);
    const horizonSol = parseInt(durationSlider.value);

    tempDisplay.textContent = `${tempC.toFixed(1)}°C`;
    durationDisplay.textContent = `${horizonSol} Sols`;

    const k = calculateRateConstant(food.arrhenius_A, food.Ea, tempC);
    const halfLifeDays = k > 0 ? Math.log(2) / k : 999999;
    const halfLifeSols = halfLifeDays / SOL_IN_EARTH_DAYS;

    eaVal.textContent = `${food.Ea.toFixed(1)} kJ/mol`;
    kVal.textContent = `${k.toFixed(5)} day⁻¹`;
    halfLifeVal.textContent = `${halfLifeDays.toFixed(0)} Earth Days`;
    dropDeadVal.textContent = `${Math.min(3000, halfLifeSols).toFixed(0)} Sols`;

    const earthDays450 = 450 * SOL_IN_EARTH_DAYS;
    const thiamineRetention450 = Math.max(0, firstOrderDecay(100.0, k, earthDays450));
    const k_c = k * 1.25;
    const vitCRetention450 = Math.max(0, firstOrderDecay(100.0, k_c, earthDays450));
    const sensoryScore450 = Math.max(1.0, food.sensory - (450 / 800) * (tempC > 20 ? 3.5 : 1.2));

    sol450Thiamine.textContent = `${thiamineRetention450.toFixed(1)}%`;
    sol450VitC.textContent = `${vitCRetention450.toFixed(1)}%`;
    sol450Sensory.textContent = `${sensoryScore450.toFixed(1)} / 10`;

    renderPredictionChart(food, tempC, horizonSol, k, k_c);
  }

  function renderPredictionChart(food, tempC, horizonSol, k_b1, k_c) {
    const svg = document.getElementById("predictionSvgChart");
    if (!svg) return;
    const w = 680, h = 280, pad = 45;

    let thiaminePath = "";
    let vitCPath = "";
    let compositePath = "";

    for (let sol = 0; sol <= horizonSol; sol += 10) {
      const eDays = sol * SOL_IN_EARTH_DAYS;
      const b1 = Math.max(0, firstOrderDecay(100.0, k_b1, eDays));
      const vc = Math.max(0, firstOrderDecay(100.0, k_c, eDays));
      const comp = 0.5 * b1 + 0.5 * vc;

      const x = pad + (sol / horizonSol) * (w - pad * 2);
      const yB1 = h - pad - (b1 / 100.0) * (h - pad * 2);
      const yVc = h - pad - (vc / 100.0) * (h - pad * 2);
      const yComp = h - pad - (comp / 100.0) * (h - pad * 2);

      thiaminePath += sol === 0 ? `M ${x} ${yB1}` : ` L ${x} ${yB1}`;
      vitCPath += sol === 0 ? `M ${x} ${yVc}` : ` L ${x} ${yVc}`;
      compositePath += sol === 0 ? `M ${x} ${yComp}` : ` L ${x} ${yComp}`;
    }

    const sol450X = pad + (Math.min(horizonSol, 450) / horizonSol) * (w - pad * 2);

    svg.innerHTML = `
      <line x1="${pad}" y1="${h - pad}" x2="${w - pad}" y2="${h - pad}" stroke="#1e293b"/>
      <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${h - pad}" stroke="#1e293b"/>
      
      <!-- 50% Threshold Drop-Dead Line -->
      <line x1="${pad}" y1="${h - pad - 0.5 * (h - pad * 2)}" x2="${w - pad}" y2="${h - pad - 0.5 * (h - pad * 2)}" stroke="#ef4444" stroke-width="1.5" stroke-dasharray="3 3"/>
      <text x="${w - pad}" y="${h - pad - 0.5 * (h - pad * 2) - 4}" fill="#ef4444" font-size="9" font-family="monospace" text-anchor="end">50% Critical Cutoff</text>
      
      <!-- Sol 450 Target Marker -->
      <line x1="${sol450X}" y1="${pad}" x2="${sol450X}" y2="${h - pad}" stroke="#f97316" stroke-width="1.5" stroke-dasharray="4 4"/>
      <text x="${sol450X}" y="${pad - 6}" fill="#f97316" font-size="10" font-weight="bold" font-family="monospace" text-anchor="middle">Sol 450 Target</text>
      
      <!-- Trajectories -->
      <path d="${thiaminePath}" fill="none" stroke="#fbbf24" stroke-width="2.5"/>
      <path d="${vitCPath}" fill="none" stroke="#10b981" stroke-width="2.5"/>
      <path d="${compositePath}" fill="none" stroke="#f97316" stroke-width="3.5" stroke-linecap="round"/>
    `;
  }

  if (foodSelect) foodSelect.addEventListener("change", updatePrediction);
  if (tempSlider) tempSlider.addEventListener("input", updatePrediction);
  if (durationSlider) durationSlider.addEventListener("input", updatePrediction);

  updatePrediction();
}

